const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');
const { URL } = require('url');

const userDataDir = '/home/node/user_data';
const historyPath = path.join(userDataDir, 'discord_chat_history.json');
const registryPath = path.join(userDataDir, 'trackers_registry.json');
const memoryPath = path.join(userDataDir, 'memory_rules.json');

if (!fs.existsSync(userDataDir)) {
  fs.mkdirSync(userDataDir, { recursive: true });
}
if (!fs.existsSync(historyPath)) {
  fs.writeFileSync(historyPath, JSON.stringify({ messages: [] }, null, 2), 'utf8');
}
if (!fs.existsSync(registryPath)) {
  fs.writeFileSync(registryPath, JSON.stringify({ trackers: {} }, null, 2), 'utf8');
}
if (!fs.existsSync(memoryPath)) {
  fs.writeFileSync(memoryPath, JSON.stringify({ morning_rules: [], custom_scopes: {} }, null, 2), 'utf8');
}

const now = new Date();
const nowIso = now.toISOString();
const todayIsoDate = nowIso.slice(0, 10);

const body = $input.first()?.json?.body || $input.first()?.json || {};
const rawText = String(body.text || '').trim();
const audioAttachment = body.audio_attachment && typeof body.audio_attachment === 'object' && body.audio_attachment.url
  ? body.audio_attachment
  : null;

// Built-in /reset or !reset command
if (['/reset', '!reset'].includes(rawText.toLowerCase())) {
  fs.writeFileSync(historyPath, JSON.stringify({ messages: [] }, null, 2), 'utf8');
  return [
    {
      json: {
        is_reset: true,
        has_audio: false,
        status: 'ok',
        reply: 'Historique de conversation réinitialisé.',
        transcribed: false,
        timestamp: nowIso
      }
    }
  ];
}

let chatHistoryObj = { messages: [] };
try {
  chatHistoryObj = JSON.parse(fs.readFileSync(historyPath, 'utf8'));
  if (!Array.isArray(chatHistoryObj.messages)) chatHistoryObj.messages = [];
} catch (e) {
  chatHistoryObj = { messages: [] };
}

const slidingWindowHistory = chatHistoryObj.messages.slice(-20);
const trackersRegistry = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
const memoryRules = JSON.parse(fs.readFileSync(memoryPath, 'utf8'));

function downloadBuffer(fileUrl, redirectsLeft = 3) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(fileUrl);
    const transport = parsed.protocol === 'https:' ? https : http;
    const req = transport.get(fileUrl, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && redirectsLeft > 0) {
        resolve(downloadBuffer(res.headers.location, redirectsLeft - 1));
        return;
      }
      if (res.statusCode < 200 || res.statusCode >= 300) {
        reject(new Error(`Audio download failed with HTTP ${res.statusCode}`));
        return;
      }
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => resolve(Buffer.concat(chunks)));
    });
    req.on('error', reject);
  });
}

let audioBase64 = null;
let audioMimeType = null;
let audioDownloadError = null;

if (audioAttachment) {
  try {
    const buf = await downloadBuffer(audioAttachment.url);
    audioBase64 = buf.toString('base64');
    audioMimeType = String(audioAttachment.content_type || 'audio/ogg').split(';')[0].trim();
  } catch (err) {
    audioDownloadError = err.message;
  }
}

return [
  {
    json: {
      is_reset: false,
      has_audio: Boolean(audioBase64),
      audio_base64: audioBase64,
      audio_mime_type: audioMimeType,
      audio_download_error: audioDownloadError,
      raw_text: rawText,
      user_message: rawText || (audioDownloadError ? `[Erreur téléchargement audio: ${audioDownloadError}]` : ''),
      transcribed: false,
      author: body.author || 'Victor',
      current_date: todayIsoDate,
      current_timestamp: nowIso,
      conversation_history: slidingWindowHistory,
      trackers_registry: trackersRegistry,
      memory_rules: memoryRules
    }
  }
];

const ctx = $('Prepare Chat Context & Audio').first().json;
const geminiRes = $input.first()?.json || {};

const transcript = String(
  geminiRes?.candidates?.[0]?.content?.parts?.[0]?.text || ''
).trim();

let combinedMessage = ctx.raw_text || '';
if (transcript) {
  combinedMessage = combinedMessage
    ? `${combinedMessage}\n[Message vocal transcrit : ${transcript}]`
    : transcript;
} else if (!combinedMessage) {
  combinedMessage = '[Message vocal reçu mais la transcription est vide]';
}

return [
  {
    json: {
      ...ctx,
      audio_base64: undefined,
      user_message: combinedMessage,
      transcribed: Boolean(transcript),
      transcript_text: transcript || null
    }
  }
];

const http = require('http');

let payload;
try {
  payload = typeof query === 'string' ? JSON.parse(query) : query;
} catch (e) {
  payload = { command: String(query || '') };
}

const commandText = String(payload.command || payload.query || query || '').trim();
if (!commandText) {
  return JSON.stringify({ error: 'command is required' });
}

const requestBody = JSON.stringify({
  command: commandText,
  notify_discord: false
});

const webhookSecret = typeof $env !== 'undefined' && $env.JARVIS_WEBHOOK_SECRET ? String($env.JARVIS_WEBHOOK_SECRET).trim() : '';

function callVoiceWebhook(hostname) {
  return new Promise((resolve, reject) => {
    const headers = {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(requestBody)
    };
    if (webhookSecret) {
      headers['X-Jarvis-Webhook-Token'] = webhookSecret;
    }
    const req = http.request(
      {
        hostname,
        port: 5678,
        path: '/webhook/voice-command',
        method: 'POST',
        headers,
        timeout: 90000
      },
      (res) => {
        let raw = '';
        res.on('data', (chunk) => { raw += chunk; });
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve(raw);
          } else {
            reject(new Error(`Voice webhook HTTP ${res.statusCode}: ${raw}`));
          }
        });
      }
    );
    req.on('timeout', () => req.destroy(new Error('Voice webhook timeout')));
    req.on('error', reject);
    req.write(requestBody);
    req.end();
  });
}

try {
  const resStr = await callVoiceWebhook('127.0.0.1');
  return resStr;
} catch (err1) {
  try {
    const resStr2 = await callVoiceWebhook('jarvis-n8n');
    return resStr2;
  } catch (err2) {
    return JSON.stringify({ error: 'Failed to call 01-voice-agent-core', details: err2.message });
  }
}

const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const historyPath = path.join(userDataDir, 'discord_chat_history.json');

const replyText = String($input.first()?.json?.output || '').trim();
const nowIso = new Date().toISOString();

let userMessage = '';
let wasTranscribed = false;
try {
  const merged = $('Merge Audio Transcription').first()?.json;
  if (merged && merged.user_message) {
    userMessage = merged.user_message;
    wasTranscribed = Boolean(merged.transcribed);
  }
} catch (e) {}

if (!userMessage) {
  const prep = $('Prepare Chat Context & Audio').first()?.json || {};
  userMessage = prep.user_message || prep.raw_text || '';
  wasTranscribed = Boolean(prep.transcribed);
}

let historyObj = { messages: [] };
if (fs.existsSync(historyPath)) {
  try {
    historyObj = JSON.parse(fs.readFileSync(historyPath, 'utf8'));
    if (!Array.isArray(historyObj.messages)) historyObj.messages = [];
  } catch (e) {
    historyObj = { messages: [] };
  }
}

if (userMessage) {
  historyObj.messages.push({
    role: 'user',
    content: userMessage,
    timestamp: nowIso
  });
}
if (replyText) {
  historyObj.messages.push({
    role: 'assistant',
    content: replyText,
    timestamp: nowIso
  });
}

// Trim stored history to the last 40 entries
historyObj.messages = historyObj.messages.slice(-40);
fs.writeFileSync(historyPath, JSON.stringify(historyObj, null, 2), 'utf8');

return [
  {
    json: {
      status: 'ok',
      reply: replyText,
      transcribed: wasTranscribed,
      timestamp: nowIso
    }
  }
];
